// The service worker: what makes the app open at all on a bad cell.
//
// It is hand-written rather than generated by a plugin, for the same reason the rest of this
// project avoids dependencies where thirty lines will do — and because the rules it has to follow
// are specific enough that a framework's defaults would be wrong:
//
//   **Nothing under /api is ever cached.** Not the ledger, not the audit trail, and above all not
//   the ID-gated documents, minutes or constitution. The API marks those `Cache-Control: no-store`
//   for exactly this reason, and a service worker that kept a copy anyway would leave a member's
//   passbook — or the group's constitution, behind its members-only gate — sitting in the browser
//   cache after the page was closed. The app has its own in-memory cache for the screens that want
//   one (services/ledgerCache) and that one forgets on reload, which is the property that matters.
//
//   **Assets are cache-first; navigation is network-first.** Vite's built assets are
//   content-hashed, so a cached `/assets/x-abc123.js` can never be stale — it is either the file
//   the HTML asks for or it is never requested. The HTML itself has to be revalidated, because it
//   is what names the new hashes.
//
//   **A new version cleans up after itself,** so a device that has been offline for a month does
//   not carry three copies of the app forever.
const CACHE = 'chama-shell-v1';

// The smallest set that makes a cold, offline launch render something real. The hashed bundles are
// picked up by the fetch handler below on first use, which is why they are not listed here.
const PRECACHE = ['/', '/index.html', '/manifest.json', '/icon.svg'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) =>
        // `addAll` rejects the whole install if any single file is missing, which would leave the
        // app with no worker at all because of one 404.
        Promise.all(PRECACHE.map((url) => cache.add(url).catch(() => {})))
      )
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((names) => Promise.all(names.filter((name) => name !== CACHE).map((name) => caches.delete(name))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Only GETs are cached. A POST is a write, and a service worker must never answer a write from
  // a cache — the offline outbox (services/offlineQueue) is where unsent writes go, and it says so
  // on screen.
  if (request.method !== 'GET') return;

  const url = new URL(request.url);

  // Same-origin only: a Cloudinary photo is not ours to cache, and caching it would keep a
  // member's face on a shared phone.
  if (url.origin !== self.location.origin) return;

  // The API, and anything the API marks uncacheable, passes straight through.
  if (url.pathname.startsWith('/api/')) return;

  // A page load: try the network so a deploy is picked up immediately, fall back to the cached
  // shell so the app still opens with no signal.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put('/index.html', copy));
          return response;
        })
        .catch(() => caches.match('/index.html').then((cached) => cached || Response.error()))
    );
    return;
  }

  // A hashed asset or a shipped file: serve from the cache when it is there, and keep a copy when
  // it is not.
  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;
      return fetch(request).then((response) => {
        if (response.ok && response.type === 'basic') {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put(request, copy));
        }
        return response;
      });
    })
  );
});
